import { useState } from 'react';


function board({value,onSquareClick}) {
  return <button className="square" onClick={onSquareClick}>{value}</button>
}



export default function GestisciClick() {
  const [squares, SetSquares] = useState(Array(9).fill(null))
  return (
    <>
    <div className="board-row">
  <Square value={squares[1]} onSquareClick={GestisciClick}/>
  <Square value={squares[2]} onSquareClick={GestisciClick}/>
  <Square value={squares[3]} onSquareClick={GestisciClick}/>
  </div>
  <div className="board-row">
  <Square value={squares[4]} onSquareClick={GestisciClick}/>
  <Square value={squares[5]} onSquareClick={GestisciClick}/>
  <Square value={squares[6]} onSquareClick={GestisciClick}/>
  </div>
  <div className="board-row">
  <Square value={squares[7]} onSquareClick={GestisciClick}/>
  <Square value={squares[8]} onSquareClick={GestisciClick}/>
  <Square value={squares[9]} onSquareClick={GestisciClick}/>
  </div>

  </>
  )
}
